<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<title>Ubuntu Desktop Simulation</title>
<style>
    :root {
        --bg-color: #1d2649; /* Dark theme background */
        --panel-color: #303a5c;
        --accent-color: #e95420; /* Ubuntu Orange-ish */
        --text-color: #eceff1;
        --window-bg: #28314d;
        --win-header: #323b57;
    }

    body, html {
        margin: 0;
        padding: 0;
        width: 100%;
        height: 100%;
        overflow: hidden;
        font-family: 'Segoe UI', Ubuntu, sans-serif;
        background-color: var(--bg-color);
    }

    #desktop {
        width: 100%;
        height: 100%;
        position: relative;
        /* Simple wallpaper simulation */
        background: linear-gradient(135deg, #2c3e50, #4ca1af); 
        user-select: none;
    }

    /* Taskbar */
    #taskbar {
        position: absolute;
        bottom: 0;
        left: 0;
        right: 0;
        height: 48px;
        background-color: rgba(255, 255, 255, 0.1);
        backdrop-filter: blur(10px);
        display: flex;
        align-items: center;
        padding: 0 16px;
        border-top: 1px solid rgba(255,255,255,0.1);
        z-index: 1000;
    }

    .launcher {
        width: 48px;
        height: 48px;
        border-radius: 8px;
        display: flex;
        align-items: center;
        justify-content: center;
        cursor: pointer;
        transition: background 0.2s, transform 0.1s;
        margin-right: 16px;
        font-size: 24px;
        color: white;
        border: none;
    }

    .launcher:hover {
        background-color: rgba(255, 255, 255, 0.2);
    }

    .launcher:active {
        transform: scale(0.95);
    }

    /* Icons */
    .icon-folder { font-size: 32px; color: #f1c40f; }
    .icon-notepad { font-size: 32px; color: #8e44ad; }

    /* Generic Window Styles */
    .window {
        position: absolute;
        background-color: var(--window-bg);
        border-radius: 6px;
        box-shadow: 0 10px 25px rgba(0,0,0,0.5);
        display: flex;
        flex-direction: column;
        overflow: hidden;
        min-width: 360px;
        min-height: 240px;
        border: 1px solid #455271;
        opacity: 0.95;
        transition: transform 0.1s, opacity 0.2s;
    }

    .window.hidden {
        display: none;
    }

    .win-header {
        height: 36px;
        background-color: var(--win-header);
        display: flex;
        align-items: center;
        padding-left: 10px;
        cursor: grab;
        border-bottom: 1px solid #2c354c;
    }

    .win-title {
        color: #b8bbbe;
        font-size: 14px;
        margin-right: auto;
        pointer-events: none;
    }

    .win-close {
        background: rgba(255,255,255,0.1);
        border: none;
        color: white;
        width: 30px;
        height: 30px;
        border-radius: 5px;
        cursor: pointer;
        font-weight: bold;
        display: flex;
        align-items: center;
        justify-content: center;
    }

    .win-close:hover { background-color: #e9182a; }

    /* Files App Specifics */
    #files-window .window-content {
        padding: 20px;
        font-size: 14px;
        color: var(--text-color);
        display: flex;
        flex-direction: column;
        height: calc(100% - 36px);
    }

    #files-path {
        font-family: monospace;
        color: #8b949e;
        margin-bottom: 15px;
        word-break: break-all;
        font-size: 12px;
    }

    .fs-list {
        display: flex;
        flex-wrap: wrap;
        gap: 8px;
        align-content: flex-start;
        flex-grow: 1;
        overflow-y: auto;
    }

    .fs-item {
        background-color: rgba(255,255,255,0.05);
        border: 1px solid transparent;
        padding: 8px 12px;
        border-radius: 4px;
        cursor: pointer;
        display: flex;
        align-items: center;
        gap: 8px;
        transition: background 0.1s, transform 0.05s;
        white-space: nowrap;
    }

    .fs-item:hover {
        background-color: rgba(255,255,255,0.1);
        border-color: rgba(255,255,255,0.15);
    }

    .fs-item i { font-size: 14px; } /* using emoji as icons */

    #files-up {
        margin-top: auto;
        padding: 8px;
        background-color: var(--accent-color);
        border-radius: 6px;
        color: white;
        border: none;
        cursor: pointer;
        font-weight: bold;
    }

    /* Notepad App Specifics */
    #notepad-window .window-content {
        display: flex;
        flex-direction: column;
        height: calc(100% - 36px);
    }

    #tabs {
        display: flex;
        background-color: #252e47;
        padding-top: 8px;
        overflow-x: auto;
    }

    .tab {
        padding: 6px 16px;
        background-color: #2d3850;
        color: #b8bbbe;
        border-radius: 4px 4px 0 0;
        margin-right: 4px;
        font-size: 12px;
        cursor: pointer;
        max-width: 120px;
        white-space: nowrap;
        overflow: hidden;
        text-overflow: ellipsis;
        user-select: none;
    }

    .tab.active {
        background-color: var(--window-bg);
        color: #e6e8eb;
        font-weight: 500;
    }

    #editor {
        flex-grow: 1;
        background-color: #2b3850;
        color: #abb2bf;
        border: none;
        resize: none;
        padding: 12px;
        font-family: 'Consolas', 'Monaco', monospace;
        font-size: 13px;
        outline: none;
    }

    .tab-bar-bottom {
        margin-top: auto;
        display: flex;
        justify-content: center;
    }

    #new-tab {
        width: 28px;
        height: 28px;
        background-color: #303a5c;
        border-radius: 4px;
        border: none;
        color: #b8bbbe;
        cursor: pointer;
        font-size: 18px;
    }
    #new-tab:hover { background-color: #e78c45; color: white; }

</style>
</head>
<body>

<div id="desktop">

    <!-- FILES WINDOW (Hidden by default) -->
    <div id="files-window" class="window hidden" style="top: 10%; left: 20%;">
        <div class="win-header">
            <div style="margin-right:10px; color:#f1c40f;">📁</div>
            <span class="win-title" id="files-window-title">File Browser</span>
            <button class="win-close">✕</button>
        </div>
        <div class="window-content">
            <div id="files-path">/</div>
            <div id="fs-list-container" class="fs-list"></div>
            <button id="files-up">⬆ Parent</button>
        </div>
    </div>

    <!-- NOTEPAD WINDOW (Hidden by default) -->
    <div id="notepad-window" class="window hidden" style="top: 10%; left: 30%;">
        <div class="win-header">
            <div style="margin-right:10px; color:#e95420;">📝</div>
            <span class="win-title">Untitled - Notepad</span>
            <button class="win-close">✕</button>
        </div>
        <div class="window-content">
            <div id="tabs"></div>
            <textarea id="editor" spellcheck="false"></textarea>
            <div class="tab-bar-bottom">
                <button id="new-tab">+</button>
            </div>
        </div>
    </div>

</div>

<!-- TASKBAR -->
<div id="taskbar">
    <!-- Launchers are positioned absolutely relative to #desktop, 
         but logically they sit inside taskbar visually or just float.
         Given the prompt says taskbar contains buttons, let's put them in taskbar container 
         for semantic correctness, though Ubuntu dock usually sits separate. 
         I will place them inside the taskbar flex layout as requested. -->

    <button id="open-files" class="launcher icon-folder">📂</button>
    <button id="open-notepad" class="launcher icon-notepad">📝</button>
</div>

<script>
    // --- File System Data Structure ---
    const fileSystem = {
        "/": [
            { name: "bin", type: "folder" },
            { name: "etc", type: "folder" },
            { name: "home", type: "folder" },
            { name: "usr", type: "folder" },
            { name: "var", type: "folder" }
        ],
        "/bin": [ { name: "ls", type: "file" }, { name: "sudo", type: "file" } ],
        "/etc": [ 
            { name: "passwd", type: "file", content: "root:x:0:0:root:/root:/bin/bash\nuser:x:1000:1000:user:/home/user:/bin/sh" },
            { name: "hosts", type: "file" }
        ],
        "/usr": [ 
             { name: "share", type: "folder" },
             { name: "local", type: "folder" },
             { name: "src", type: "folder" }
        ],
        "/var": [ 
            { name: "log", type: "folder" },
            { name: "cache", type: "folder" }
        ],
        "/home": [ { name: "user", type: "folder" } ],
        "/usr/share": [ { name: "data", type: "folder" } ],
        "/usr/local": [], 
        "/usr/src": [ { name: "app1.js", type: "file", content: "// Application Source" }],

        "/var/log": [ { name: "syslog.txt", type: "file", content: "Oct 24 10:00:00 system starting up\nOct 24 10:05:00 user login" } ],

        "/home/user": [ 
            { name: "Documents", type: "folder" },
            { name: "Downloads", type: "folder" },
            { name: "Pictures", type: "folder" },
            { name: "notes.txt", type: "file", content: "Hello World\nThis is a text file in /home/user." }
        ],

        "/home/user/Documents": [ 
            { name: "resume.pdf", type: "file" },
            { name: "project.zip", type: "file" }
        ],
        "/home/user/Downloads": [ 
             { name: "ubuntu-logo.png", type: "file" },
             { name: "install.sh", type: "file", content: "#!/bin/bash\necho 'Installing Ubuntu...'" }
        ],
        "/home/user/Pictures": [ { name: "cat.jpg", type: "file" } ]
    };

    // --- State Management ---
    const state = {
        currentPath: "/",
        openWindows: ['files', 'notepad'], // Track if window is visible (conceptually)
        notepadTabs: [] // Array of tab objects, persisted to localStorage
    };

    // --- DOM Elements ---
    const els = {
        desktop: document.getElementById('desktop'),
        taskbar: document.getElementById('taskbar'),

        filesWindow: document.getElementById('files-window'),
        filesPath: document.getElementById('files-path'),
        fsListContainer: document.getElementById('fs-list-container'),
        filesUp: document.getElementById('files-up'),

        notepadWindow: document.getElementById('notepad-window'),
        tabsContainer: document.getElementById('tabs'),
        editor: document.getElementById('editor'),
        newTabBtn: document.getElementById('new-tab'),
    };

    // --- Event Listeners for Shell ---

    // Open Files App
    els.taskbar.querySelector('#open-files').addEventListener('click', () => {
        if (!els.filesWindow.classList.contains('hidden')) return; // Already open, focus it?
        showWindow(els.filesWindow);
    });

    // Open Notepad App
    els.taskbar.querySelector('#open-notepad').addEventListener('click', () => {
        if (!els.notepadWindow.classList.contains('hidden')) return;
        showWindow(els.notepadWindow);
    });

    function showWindow(el) {
        el.classList.remove('hidden');
        // Focus behavior could be added here, but for now just visual display
    }

    // Close Button Delegation (Generic approach: attach listeners to .win-close buttons via delegation or directly)
    document.body.addEventListener('click', (e) => {
        const winCloseBtn = e.target.closest('.win-close');
        if (winCloseBtn && !winCloseBtn.parentElement.classList.contains('hidden')) {
            // Check window type based on parent ID
            const parent = winCloseBtn.closest('.window');

            if (parent.id === 'files-window') {
                els.filesWindow.classList.add('hidden');
            } else if (parent.id === 'notepad-window') {
                saveNotepadData(); // Save before hiding
                els.notepadWindow.classList.add('hidden');
            }
        }
    });

    // --- File System Logic ---

    function renderFileList(path) {
        const currentFolder = fileSystem[path];
        els.fsListContainer.innerHTML = '';

        if (!currentFolder) return;

        currentFolder.forEach((item, index) => {
            const div = document.createElement('div');
            div.className = 'fs-item';

            let icon = item.type === 'folder' ? '📁 ' : '📄 ';
            if (item.name.includes('.sh') || item.name.includes('.txt')) icon = item.type === 'file' ? '📜 ' : '📁 '; 
            // Specific icons for clarity

            let label = item.name;

            div.innerHTML = `<span style="font-size:14px">${icon}${label}</span>`;

            // Double Click Logic
            div.addEventListener('dblclick', () => {
                if (item.type === 'folder') {
                    navigateTo(path + '/' + index);
                } else {
                    // Treat file click as up for simplicity or open dummy reader
                    // Requirement says double click folder navigates. 
                    // I will assume single click is not implemented, only double click action defined.
                }
            });

            els.fsListContainer.appendChild(div);
        });
    }

    function navigateTo(path) {
        state.currentPath = path;
        renderFileList(path);

        // Update Path Label
        els.filesPath.innerText = path === "/" ? "/" : (path.substring(0, 10).replace(/\//g, ' ') || path);
        if(state.currentPath.length > 30) {
            // Shorten for display if too long
             let tempPath = state.currentPath.split('/');
             let display = "/";
             for(let p of tempPath) display += p + "/";
             els.filesPath.innerText = display; 
        } else {
             els.filesPath.innerText = state.currentPath;
        }
    }

    function navigateToParent() {
        const parts = state.currentPath.split('/');
        if (parts.length > 1) {
            parts.pop(); // Remove last item (which is an index number, so this removes the last component)
            navigateTo(parts.join('/'));
        } else {
            navigateTo("/");
        }
    }

    els.filesUp.addEventListener('click', navigateToParent);

    // --- Notepad Logic ---

    function saveNotepadData() {
        // Save current active tab or all tabs? 
        // Requirement: "persistent... closing... restoring every tab"
        // Simplest robust approach: The editor content is associated with the visible tab.
        // When reloading, we need to reconstruct tabs from LocalStorage.

        // Let's store a list of objects in localStorage.
        const data = JSON.stringify(state.notepadTabs);
        localStorage.setItem('desktop_notepad_data', data);
    }

    function loadNotepadData() {
        const stored = localStorage.getItem('desktop_notepad_data');
        if (stored) {
            state.notepadTabs = JSON.parse(stored);
        } else {
            // Default tab on first run if empty
            if (state.notepadTabs.length === 0) {
                addTab("New Tab", "");
            }
        }
    }

    function switchTab(tabId) {
        state.notepadTabs.forEach(t => {
            const el = document.getElementById(`tab-${t.id}`);
            if(el) el.classList.remove('active');
            t.isActive = false;
        });

        const target = state.notepadTabs.find(t => t.id === tabId);
        if(target && target.text) { // Check text is not null/undefined for empty new tabs
             els.editor.value = target.text || "";
        } else if (target) {
            // If we switched to an "empty" tab state that saved as empty, restore it
            // This logic relies on saving empty tabs as "" so they persist. 
            // The `addTab` function sets text="" immediately.
             els.editor.value = "";
        }

        target.isActive = true;

        // Update UI classes
        const tabEl = document.getElementById(`tab-${target.id}`);
        if(tabEl) tabEl.classList.add('active');
    }

    // Notepad App Construction
    function addTab(title, textContent = "") {
        const id = Date.now().toString(); // Simple ID generation

        const tabObj = {
            id: id,
            title: title || "Untitled",
            text: textContent || "",
            isActive: false
        };

        state.notepadTabs.push(tabObj);

        // UI Construction
        const tabDiv = document.createElement('div');
        tabDiv.className = 'tab';
        tabDiv.id = `tab-${id}`;
        tabDiv.innerText = title || "New Tab";
        if (state.notepadTabs.length === 1) tabDiv.classList.add('active'); // Auto-active first

        tabDiv.addEventListener('click', () => switchTab(id));

        els.tabsContainer.appendChild(tabDiv);

        const textareaVal = document.getElementById('editor');
        textareaVal.value = textContent || "";

        return id;
    }

    function createNewTab() {
        const newId = addTab("New Tab");
        // Switch to it immediately? Not strictly required, but good UX. 
        // Requirement: "#new-tab creates a new empty tab"
        switchTab(newId);
    }

    els.newTabBtn.addEventListener('click', createNewTab);

    // Initial Setup
    function init() {
        loadNotepadData();
        els.editor.focus();

        // Add initial dummy content to first tab so user sees something
        if (state.notepadTabs.length > 0) {
             const t = state.notepadTabs[0];
             if(!t.text && !document.getElementById('tabs').children.length > 0) {
                els.editor.value = "# Welcome to Ubuntu Notepad\n# Double click folder in file explorer to browse.\n# Tabbed editing with persistence enabled.";
                // Wait, we load data from LS. If LS is empty, text is "".
                // But the first tab might be the "default" one that user created implicitly.
             }
        }

        // Render Files Window
        navigateTo("/");

        // Close buttons specifically for notepad to persist before close? 
        // We rely on event delegation in body listener to trigger saveThenHide
    }

    init();

</script>
</body>
</html>
